    /// INLINE MMIO (S2g): a load/store that `Fm` rejects (hardware register, DMA, VU mirror ...) runs through the recompiled code's own slow path
    /// (`hs_fast::mmio`: the interpreter runs that ONE instruction at icount `ic`, then the event check over `rem` more instructions), no deopt.
    ///   `let v = ld32!(c, fr, fm, ADDR, DST, PC, IC, REM);`   `st32!(c, fr, fm, ADDR, VALUE, PC, IC, REM);`   (widths 8 16 32 64 128)
    /// `ADDR`: u32 effective address (lq/sq: the macro rounds it down to 16 like `Fm`). `DST`: the GPR number of the load's destination. `VALUE`: the value to store
    /// (u8..u128). `PC`: the instruction's pc (a plain load/store, NOT in a delay slot). `IC`: instruction count AFTER it (block-start count + index in the block + 1).
    /// `REM`: instructions after it up to the next due check or region exit (rec's value: block length - index - 1; a loop hand: the longest path to the header).
    /// The load's value is the RAW width (u8..u128, from `Fm` or from the register the hardware access wrote): apply the retail extension yourself (lw: `sx32`).
    /// `flush!()` runs before the slow path (the access reads/writes `c`), so every local the region modified is current; after the access reload any local that
    /// aliases `DST`, and in a region with a VU0 `Chop` call `g.begin()` (flush ended it). Fast path = one `Fm` access, exactly as before.
    /// S6f: after a slow access that did not deopt the macro puts c.icount back to its value before the access (the block total of `blk`), so
    /// no `c.icount = ...` restore is needed after it.
    macro_rules! mmio_ld {
        ($c:expr, $fr:expr, $fm:expr, $rd:ident, $ty:ty, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => {{
            match $fm.$rd($a) {
                Some(v) => v,
                None => {
                    let ick = $c.icount; // S6f: the slow path sets c.icount to IC; the hand's count is the block total (blk)
                    flush!();
                    if !crate::hs_fast::mmio($c, $pc, $ic, $rem) {
                        return crate::hs::deopt($c, $fr, ($pc as u32).wrapping_add(4), $c.icount);
                    }
                    $c.icount = ick;
                    $c.r[$dst] as $ty
                }
            }
        }};
    }
    macro_rules! mmio_st {
        ($c:expr, $fr:expr, $fm:expr, $wr:ident, $a:expr, $v:expr, $pc:expr, $ic:expr, $rem:expr) => {{
            if !$fm.$wr($a, $v) {
                let ick = $c.icount; // S6f: see mmio_ld!
                flush!();
                if !crate::hs_fast::mmio($c, $pc, $ic, $rem) {
                    return crate::hs::deopt($c, $fr, ($pc as u32).wrapping_add(4), $c.icount);
                }
                $c.icount = ick;
            }
        }};
    }
    macro_rules! ld8 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r8, u8, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld16 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r16, u16, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld32 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r32, u32, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld64 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r64, u64, $a, $dst, $pc, $ic, $rem) }; }
    macro_rules! ld128 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r128, u128, $a, $dst, $pc, $ic, $rem) }; }
