                    v2 = v2.blend::<7>(r);
                    fl!(r);
                    let x = ld32!(c, fr, fm, (t4 as u32).wrapping_add(0xc), 12, fr.pc(0xbf8), ic0 + 8, 8);
                    t4 = sx32(x);
                    rearm!();
                    // vmuly.xyz vf3, vf3, vf1y
                    let r = v3.prep().mul(v1.prep().bcy());
                    v3 = v3.blend::<7>(r);
                    fl!(r);
